const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const evalEE = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));
  const dateStr = '2002-08-14';
  const targetDate = ee.Date(dateStr);
  const exactStart = targetDate;
  const exactEnd = targetDate.advance(1, 'day');
  const fallbackStart = targetDate.advance(-7, 'day');
  const fallbackEnd = targetDate.advance(8, 'day');

  // NYC geometry
  const places = ee.FeatureCollection('TIGER/2018/Places')
    .filter(ee.Filter.and(ee.Filter.eq('STATEFP', '36'), ee.Filter.eq('NAME', 'New York')));
  const nyc = ee.Feature(places.first());
  const nycGeom = ee.Algorithms.If(places.size().gt(0), ee.Feature(places.first()).geometry(), ee.Geometry.Point([-73.98, 40.75]).buffer(25000));
  const region = ee.Geometry(nycGeom);

  // Collections
  const l7Exact = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').filterDate(exactStart, exactEnd).filterBounds(region);
  const l5Exact = ee.ImageCollection('LANDSAT/LE05/C02/T1_L2').filterDate(exactStart, exactEnd).filterBounds(region);

  let l7ExactSize = await evalEE(l7Exact.size());
  let l5ExactSize = await evalEE(l5Exact.size());

  let chosen = null;
  let sensor = null;
  let source = 'exact';
  let notes = [];

  if (l7ExactSize > 0) {
    chosen = l7Exact.sort('CLOUD_COVER').first();
    sensor = 'LE07';
  } else if (l5ExactSize > 0) {
    chosen = l5Exact.sort('CLOUD_COVER').first();
    sensor = 'LE05';
  } else {
    notes.push('Exact-date images: 0 → fallback ±7 days');
    source = 'fallback±7d';
    const l7Win = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').filterDate(fallbackStart, fallbackEnd).filterBounds(region);
    const l5Win = ee.ImageCollection('LANDSAT/LE05/C02/T1_L2').filterDate(fallbackStart, fallbackEnd).filterBounds(region);
    const l7WinSize = await evalEE(l7Win.size());
    const l5WinSize = await evalEE(l5Win.size());
    if ((l7WinSize || 0) + (l5WinSize || 0) === 0) {
      console.log('Target date:', dateStr);
      console.log('LE07 exact images:', l7ExactSize || 0, '| LE05 exact images:', l5ExactSize || 0);
      console.log('Fallback ±7d: LE07 images:', l7WinSize || 0, '| LE05 images:', l5WinSize || 0);
      console.log('C1: Empty Collection (No images found in date/location)');
      console.log('C1');
      return;
    }
    // Choose nearest by time difference, then by CLOUD_COVER
    const addDiff = (col) => col.map(function(img) {
      const diff = img.date().difference(targetDate, 'day').abs();
      return img.set('timediff', diff);
    });
    const l7Cand = addDiff(l7Win).sort('timediff').sort('CLOUD_COVER');
    const l5Cand = addDiff(l5Win).sort('timediff').sort('CLOUD_COVER');
    const bestL7 = l7WinSize > 0 ? l7Cand.first() : null;
    const bestL5 = l5WinSize > 0 ? l5Cand.first() : null;
    let pickL7 = null, pickL5 = null;
    if (bestL7) pickL7 = ee.Image(bestL7);
    if (bestL5) pickL5 = ee.Image(bestL5);
    let tdL7 = pickL7 ? await evalEE(pickL7.get('timediff')) : null;
    let tdL5 = pickL5 ? await evalEE(pickL5.get('timediff')) : null;
    if (tdL7 != null && (tdL5 == null || tdL7 <= tdL5)) {
      chosen = pickL7;
      sensor = 'LE07';
    } else if (tdL5 != null) {
      chosen = pickL5;
      sensor = 'LE05';
    }
  }

  if (!chosen) {
    console.log('Target date:', dateStr);
    console.log('C1: Empty Collection (No selectable image)');
    console.log('C1');
    return;
  }

  // Image info
  const imgId = await evalEE(chosen.get('LANDSAT_SCENE_ID').cat(ee.String('')).aside ? chosen.get('LANDSAT_SCENE_ID') : chosen.get('SYSTEM_INDEX'));
  const imgDate = await evalEE(ee.Date(chosen.get('system:time_start')).format('YYYY-MM-dd'));
  const cloudCover = await evalEE(chosen.get('CLOUD_COVER'));
  // QA mask + scaling + NDVI + ST
  function prepLxL2(img) {
    var qa = img.select('QA_PIXEL');
    var mask = qa.bitwiseAnd(1 << 0).eq(0) // not fill
      .and(qa.bitwiseAnd(1 << 1).eq(0))    // not dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0))    // not cirrus
      .and(qa.bitwiseAnd(1 << 3).eq(0))    // not cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0))    // not cloud shadow
      .and(qa.bitwiseAnd(1 << 5).eq(0));   // not snow

    var rednir = img.select(['SR_B3', 'SR_B4'], ['red', 'nir'])
      .multiply(0.0000275).add(-0.2);
    var ndvi = rednir.normalizedDifference(['nir', 'red']).rename('ndvi');

    var stB6 = img.select(['ST_B6'], ['stb6']);
    var tempK = stB6.multiply(0.00341802).add(149.0).rename('tempK');
    var tempC = tempK.subtract(273.15).rename('tempC');

    return ee.Image.cat([ndvi, tempC]).updateMask(mask);
  }
  let img = prepLxL2(chosen);

  // Non-water mask using JRC
  const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
  const notWater = gsw.lt(50);
  const footprint = ee.Geometry(chosen.geometry());
  const useRegion = region.intersection(footprint, 1);
  const landMaskImg = ee.Image(1).updateMask(notWater).clip(useRegion).rename('ones');

  // Apply land mask
  img = img.updateMask(notWater).clip(useRegion);

  // Counts
  const landTotal = await evalEE(landMaskImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: useRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('ones'));

  const validCount = await evalEE(img.select('ndvi').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: useRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('ndvi'));

  const ndviMean = await evalEE(img.select('ndvi').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: useRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('ndvi'));

  const tempMeanC = await evalEE(img.select('tempC').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: useRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('tempC'));

  if (!landTotal || landTotal === 0) {
    console.log('Target date:', dateStr);
    console.log('Image:', sensor, String(imgId || ''), '| Date used:', imgDate, '| CLOUD_COVER:', cloudCover);
    console.log('Land pixels:', landTotal || 0);
    console.log('C2: No Valid Pixels (No land pixels in region/footprint)');
    console.log('C2');
    return;
  }
  if (!validCount || validCount === 0) {
    const cloudPct = Math.round((1 - 0 / landTotal) * 1000) / 10;
    console.log('Target date:', dateStr);
    console.log('Image:', sensor, String(imgId || ''), '| Date used:', imgDate, '| CLOUD_COVER:', cloudCover);
    console.log('Land pixels:', landTotal, '| Valid pixels:', 0, '| Cloud/Invalid %:', cloudPct + '%');
    console.log('C2: No Valid Pixels (All masked by clouds/QA/water)');
    console.log('C2');
    return;
  }

  // Linear fit Temp vs NDVI
  const fit = await evalEE(img.select(['ndvi', 'tempC']).reduceRegion({
    reducer: ee.Reducer.linearFit(),
    geometry: useRegion,
    scale: 1000,
    maxPixels: 1e9
  }));
  const slope = fit ? fit.scale : null;      // degC per NDVI unit
  const r2 = fit ? fit.rSquared : null;

  // Validate slope/r2
  const slopeNum = Number(slope);
  const r2Num = Number(r2);
  if (!Number.isFinite(slopeNum) || !Number.isFinite(r2Num)) {
    console.log('Target date:', dateStr);
    console.log('Image:', sensor, String(imgId || ''), '| Date used:', imgDate, '| CLOUD_COVER:', cloudCover);
    console.log('Land pixels:', landTotal, '| Valid pixels:', validCount);
    console.log('C3: Calculation Failure (Invalid slope/r2)');
    console.log('C3');
    return;
  }

  const cloudPct = Math.round((1 - validCount / landTotal) * 1000) / 10;
  console.log('Target date:', dateStr, '| Mode:', source);
  console.log('Image:', sensor, String(imgId || ''), '| Date used:', imgDate, '| CLOUD_COVER:', cloudCover);
  console.log('Land pixels:', landTotal, '| Valid pixels:', validCount, '| Cloud/Invalid %:', cloudPct + '%');
  console.log('NDVI mean:', (ndviMean !== null && ndviMean !== undefined) ? Number(ndviMean).toFixed(3) : 'NA',
              '| Temp mean (°C):', (tempMeanC !== null && tempMeanC !== undefined) ? Number(tempMeanC).toFixed(2) : 'NA');
  console.log('Linear fit: Temp(°C) = slope*NDVI + offset; slope:', slopeNum.toFixed(3), '| r2:', r2Num.toFixed(3));

  // Final decision: temperature decreases with higher vegetation density if slope < 0
  if (slopeNum < 0) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (err) {
    console.log('D: Error initializing or running analysis:', err && err.message ? err.message : String(err));
    console.log('D');
  }
}

initEE();
